window.__QUIZ_CHUNKS__ = (window.__QUIZ_CHUNKS__ || {});
window.__QUIZ_CHUNKS__.B1 = {"B1":{"vocab":[{"id":"q-vocab-b1-0001","level":"B1","skill":"vocab","prompt":"「Il a le sens des responsabilités.」的意思是：","options":["他很有责任感","他负责一个部门","他出过责任事故","他很负责地拒绝了"],"answer":"他很有责任感","explain":"avoir le sens des responsabilités 指有责任感；负责某个部门是 être responsable d'un service，责任事故是 accident dont il est responsable，与拒绝无关。","source":"词汇 · 一、人与身份（identité） · vocab.html#t1-titre"},{"id":"q-vocab-b1-0002","level":"B1","skill":"vocab","prompt":"「être majeur / être mineur」的意思是：","options":["已成年 / 未成年","主要的 / 次要的","大人物 / 小人物","高兴的 / 难过的"],"answer":"已成年 / 未成年","explain":"majeur / mineur 在法律语境指成年与未成年；主要和次要是 principal / secondaire，大人物是 personnalité，高兴是 content。","source":"词汇 · 一、人与身份（identité） · vocab.html#t1-titre"},{"id":"q-vocab-b1-0003","level":"B1","skill":"vocab","prompt":"「Il a élevé ses enfants seul.」中 élever 的意思是：","options":["抚养、养育","提高（价格）","举起（手）","提出（问题）"],"answer":"抚养、养育","explain":"élever 有「抚养」和「提高、举起」两义，这里宾语是 enfants，所以是养育；提高价格是 augmenter les prix，举手是 lever la main，提出问题是 poser une question。","source":"词汇 · 二、家庭与关系（famille） · vocab.html#t2-titre"},{"id":"q-vocab-b1-0004","level":"B1","skill":"vocab","prompt":"「une famille recomposée」的意思是：","options":["重组家庭","大家庭","独生子女家庭","寄养家庭"],"answer":"重组家庭","explain":"famille recomposée 指父母带各自的孩子重新组成的家庭；大家庭是 famille nombreuse，独生子女家庭是 famille avec un enfant unique，寄养家庭是 famille d'accueil。","source":"词汇 · 二、家庭与关系（famille） · vocab.html#t2-titre"},{"id":"q-vocab-b1-0005","level":"B1","skill":"vocab","prompt":"「Il souffre de migraines.」的意思是：","options":["他受偏头痛之苦","他假装头疼","他治疗头痛","他把头痛传染给了别人"],"answer":"他受偏头痛之苦","explain":"souffrir de + 疾病表示患某种病并受其折磨；假装是 faire semblant，治疗是 soigner，传染是 contaminer。","source":"词汇 · 三、身体与健康（santé） · vocab.html#t3-titre"},{"id":"q-vocab-b1-0006","level":"B1","skill":"vocab","prompt":"「être en bonne santé」的意思是：","options":["身体健康","健康保险","健康饮食","医疗费用"],"answer":"身体健康","explain":"être en bonne santé 指身体状况良好；健康保险是 assurance maladie，健康饮食是 alimentation saine，医疗费用是 frais médicaux。","source":"词汇 · 三、身体与健康（santé） · vocab.html#t3-titre"},{"id":"q-vocab-b1-0007","level":"B1","skill":"vocab","prompt":"「Il est têtu comme une mule.」的意思是：","options":["他非常固执","他力气很大","他很勤劳","他脾气暴躁"],"answer":"他非常固执","explain":"têtu 是固执，têtu comme une mule 是「犟得像头骡子」；力气大是 fort，勤劳是 travailleur，脾气暴躁是 colérique。","source":"词汇 · 四、外貌与性格（caractère） · vocab.html#t4-titre"},{"id":"q-vocab-b1-0008","level":"B1","skill":"vocab","prompt":"「Elle a le sens de l'humour.」的意思是：","options":["她有幽默感","她很爱笑","她喜欢恶作剧","她很严肃"],"answer":"她有幽默感","explain":"avoir le sens de l'humour 指有幽默感；爱笑是 souriant，恶作剧是 faire des farces，严肃是 sérieux。","source":"词汇 · 四、外貌与性格（caractère） · vocab.html#t4-titre"},{"id":"q-vocab-b1-0009","level":"B1","skill":"vocab","prompt":"「une colocation」的意思是：","options":["合租","共同产权","临时住所","家具租赁"],"answer":"合租","explain":"colocation 指几个人合租一套住房（colocataire 是室友）；共同产权是 copropriété，临时住所是 hébergement temporaire，家具租赁是 location de meubles。","source":"词汇 · 五、房屋与居住（logement） · vocab.html#t5-titre"},{"id":"q-vocab-b1-0010","level":"B1","skill":"vocab","prompt":"「les charges comprises」的意思是：","options":["含物业费","含家具","含停车位","含全部水电网用量"],"answer":"含物业费","explain":"charges comprises 指租金包含物业杂费；含家具是 meublé，含停车位是 avec parking，而「全部用量」超出了 charges 的通常含义。","source":"词汇 · 五、房屋与居住（logement） · vocab.html#t5-titre"},{"id":"q-vocab-b1-0011","level":"B1","skill":"vocab","prompt":"「une spécialité régionale」的意思是：","options":["地方特色菜","特价菜","季节性菜单","小吃摊"],"answer":"地方特色菜","explain":"spécialité régionale 指某地区的特色菜；特价菜是 plat du jour 或 promotion，季节性菜单是 menu de saison，小吃摊是 stand de restauration。","source":"词汇 · 六、食物与餐饮（alimentation） · vocab.html#t6-titre"},{"id":"q-vocab-b1-0012","level":"B1","skill":"vocab","prompt":"「Il est allergique aux fruits à coque.」中 fruits à coque 指：","options":["坚果","带核水果","干果","果酱"],"answer":"坚果","explain":"fruits à coque 指核桃、杏仁、榛子等坚果；带核水果是 fruits à noyau，干果是 fruits secs，果酱是 confiture。","source":"词汇 · 六、食物与餐饮（alimentation） · vocab.html#t6-titre"},{"id":"q-vocab-b1-0013","level":"B1","skill":"vocab","prompt":"「un achat impulsif」的意思是：","options":["冲动消费","分期付款","团购","退货"],"answer":"冲动消费","explain":"achat impulsif 指没计划就下单；分期付款是 paiement en plusieurs fois，团购是 achat groupé，退货是 retour d'un article。","source":"词汇 · 七、购物与消费（achats） · vocab.html#t7-titre"},{"id":"q-vocab-b1-0014","level":"B1","skill":"vocab","prompt":"「Je me suis fait rembourser.」的意思是：","options":["我拿到了退款","我付了定金","我被罚了款","我办了会员卡"],"answer":"我拿到了退款","explain":"rembourser 是退款，se faire rembourser 是拿到退款；付定金是 verser un acompte，被罚款是 être verbalisé，办会员卡是 prendre une carte de fidélité。","source":"词汇 · 七、购物与消费（achats） · vocab.html#t7-titre"},{"id":"q-vocab-b1-0015","level":"B1","skill":"vocab","prompt":"「une tenue correcte exigée」的意思是：","options":["要求着装得体","要求统一穿制服","要求穿晚礼服","要求换鞋进入"],"answer":"要求着装得体","explain":"tenue correcte exigée 指要求穿着得体；统一制服是 uniforme，晚礼服是 tenue de soirée，换鞋与本短语无关。","source":"词汇 · 八、衣物与时尚（vêtements） · vocab.html#t8-titre"},{"id":"q-vocab-b1-0016","level":"B1","skill":"vocab","prompt":"「Ces chaussures me font mal.」的意思是：","options":["这双鞋磨脚","这双鞋很贵","这双鞋很时髦","这双鞋是仿制品"],"answer":"这双鞋磨脚","explain":"faire mal 表示让人疼痛、磨脚；很贵是 coûter cher，时髦是 à la mode，仿制品是 contrefaçon。","source":"词汇 · 八、衣物与时尚（vêtements） · vocab.html#t8-titre"},{"id":"q-vocab-b1-0017","level":"B1","skill":"vocab","prompt":"「un abonnement mensuel」的意思是：","options":["月票（月度订阅）","单程票","出租车费","停车罚单"],"answer":"月票（月度订阅）","explain":"abonnement 是定期票、订阅（s'abonner 订阅）；单程票是 ticket simple，车费是 tarif，罚单是 contravention。","source":"词汇 · 九、城市与交通（transports） · vocab.html#t9-titre"},{"id":"q-vocab-b1-0018","level":"B1","skill":"vocab","prompt":"「un embouteillage」的意思是：","options":["交通堵塞","交通事故","道路施工","超速行驶"],"answer":"交通堵塞","explain":"embouteillage 指堵车；交通事故是 accident，道路施工是 travaux，超速是 excès de vitesse。","source":"词汇 · 九、城市与交通（transports） · vocab.html#t9-titre"},{"id":"q-vocab-b1-0019","level":"B1","skill":"vocab","prompt":"「un séjour linguistique」的意思是：","options":["语言游学","商务出差","一日游","长途飞行"],"answer":"语言游学","explain":"séjour linguistique 指为学语言而住的短期游学；商务出差是 voyage d'affaires，一日游是 excursion d'une journée，长途飞行与 séjour 无关。","source":"词汇 · 十、旅行与度假（voyages） · vocab.html#t10-titre"},{"id":"q-vocab-b1-0020","level":"B1","skill":"vocab","prompt":"「partir en dernière minute」的意思是：","options":["最后一刻出发（临时订的行程）","迟到出发","最后一个离开","提前出发"],"answer":"最后一刻出发（临时订的行程）","explain":"dernière minute 指临行前才决定的特价行程；迟到是 partir en retard，最后离开是 être le dernier à partir，提前是 partir plus tôt。","source":"词汇 · 十、旅行与度假（voyages） · vocab.html#t10-titre"},{"id":"q-vocab-b1-0021","level":"B1","skill":"vocab","prompt":"「Il a été licencié.」的意思是：","options":["他被解雇了","他辞职了","他升职了","他退休了"],"answer":"他被解雇了","explain":"licencier 指（雇主）解雇；辞职是 démissionner，升职是 être promu，退休是 prendre sa retraite。","source":"词汇 · 十一、工作与职业（travail） · vocab.html#t11-titre"},{"id":"q-vocab-b1-0022","level":"B1","skill":"vocab","prompt":"「un emploi du temps chargé」的意思是：","options":["安排得很满的日程","一份临时工作","一份高薪工作","一份全职合同"],"answer":"安排得很满的日程","explain":"emploi du temps 指时间表，chargé 指排得满；临时工作是 travail temporaire，高薪是 bien payé，全职合同是 CDI。","source":"词汇 · 十一、工作与职业（travail） · vocab.html#t11-titre"},{"id":"q-vocab-b1-0023","level":"B1","skill":"vocab","prompt":"「une bourse d'études」的意思是：","options":["奖学金","学费","学生证","交换项目"],"answer":"奖学金","explain":"bourse d'études 是奖学金（bourse 也可指证券交易所，靠语境区分）；学费是 frais de scolarité，学生证是 carte d'étudiant，交换项目是 programme d'échange。","source":"词汇 · 十二、教育与学习（éducation） · vocab.html#t12-titre"},{"id":"q-vocab-b1-0024","level":"B1","skill":"vocab","prompt":"「rattraper un cours」的意思是：","options":["补上缺的课","追赶同学","复习功课","去旁听课程"],"answer":"补上缺的课","explain":"rattraper un cours 指把落下的课补回来；复习是 réviser，旁听是 assister à un cours，追赶同学与该搭配不符。","source":"词汇 · 十二、教育与学习（éducation） · vocab.html#t12-titre"},{"id":"q-vocab-b1-0025","level":"B1","skill":"vocab","prompt":"「Il y a une éternité que je ne l'ai pas vu.」的意思是：","options":["我很久没见他了","我永远不想见他","我刚见过他","我每天都见他"],"answer":"我很久没见他了","explain":"une éternité 在这里夸张地表示「很久」；永远不见是 ne plus jamais le voir，刚见过是 venir de le voir，每天见是 le voir tous les jours。","source":"词汇 · 十三、数字、时间与度量（nombres et temps） · vocab.html#t13-titre"},{"id":"q-vocab-b1-0026","level":"B1","skill":"vocab","prompt":"「à peu près」的意思是：","options":["大约","几乎不","确切地","立刻"],"answer":"大约","explain":"à peu près 表约略估计；几乎不是 ne… presque pas，确切地是 exactement，立刻是 tout de suite。","source":"词汇 · 十三、数字、时间与度量（nombres et temps） · vocab.html#t13-titre"},{"id":"q-vocab-b1-0027","level":"B1","skill":"vocab","prompt":"「une sécheresse historique」的意思是：","options":["历史性的干旱","历史性的洪水","历史性的暴风","历史性的寒潮"],"answer":"历史性的干旱","explain":"sécheresse 是干旱；洪水是 inondation，暴风是 tempête，寒潮是 vague de froid。","source":"词汇 · 十四、天气与自然（météo et nature） · vocab.html#t14-titre"},{"id":"q-vocab-b1-0028","level":"B1","skill":"vocab","prompt":"「le littoral」的意思是：","options":["沿海地带","内陆地区","山区","河岸"],"answer":"沿海地带","explain":"littoral 指沿海地带；内陆是 l'intérieur des terres，山区是 région montagneuse，河岸是 rive。","source":"词汇 · 十四、天气与自然（météo et nature） · vocab.html#t14-titre"},{"id":"q-vocab-b1-0029","level":"B1","skill":"vocab","prompt":"「les données personnelles」的意思是：","options":["个人数据","情报人员","个人账户","私人信件"],"answer":"个人数据","explain":"données 是数据（données personnelles 是个人数据）；情报人员是 informateur，个人账户是 compte personnel，私人信件是 lettres privées。","source":"词汇 · 十五、科技与互联网（technologie） · vocab.html#t15-titre"},{"id":"q-vocab-b1-0030","level":"B1","skill":"vocab","prompt":"「une faille de sécurité」的意思是：","options":["安全漏洞","安全检查","安全保险","安全培训"],"answer":"安全漏洞","explain":"faille 指漏洞、缺陷；检查是 contrôle，保险是 assurance，培训是 formation。","source":"词汇 · 十五、科技与互联网（technologie） · vocab.html#t15-titre"},{"id":"q-vocab-b1-0031","level":"B1","skill":"vocab","prompt":"「un abonné au journal」的意思是：","options":["报纸订户","报社记者","报纸广告商","报摊摊主"],"answer":"报纸订户","explain":"abonné 是订户、订阅者（s'abonner 是订阅）；记者是 journaliste，广告商是 annonceur，报摊摊主是 vendeur de journaux。","source":"词汇 · 十六、媒体与娱乐（médias et loisirs） · vocab.html#t16-titre"},{"id":"q-vocab-b1-0032","level":"B1","skill":"vocab","prompt":"「une critique élogieuse」的意思是：","options":["好评","差评","中立评论","抄袭指控"],"answer":"好评","explain":"élogieux 意为赞扬的；差评是 critique négative，中立评论是 critique neutre，抄袭指控是 accusation de plagiat。","source":"词汇 · 十六、媒体与娱乐（médias et loisirs） · vocab.html#t16-titre"},{"id":"q-vocab-b1-0033","level":"B1","skill":"vocab","prompt":"「battre un record」的意思是：","options":["打破纪录","输掉比赛","取消比赛","记录训练数据"],"answer":"打破纪录","explain":"battre un record 是破纪录；输掉比赛是 perdre un match，取消比赛是 annuler un match，训练是 s'entraîner。","source":"词汇 · 十七、体育与休闲（sports） · vocab.html#t17-titre"},{"id":"q-vocab-b1-0034","level":"B1","skill":"vocab","prompt":"「une randonnée en montagne」的意思是：","options":["山间徒步","登山竞赛","山地自行车","露营"],"answer":"山间徒步","explain":"randonnée 是徒步远足；登山竞赛是 compétition d'escalade，山地自行车是 VTT，露营是 camping。","source":"词汇 · 十七、体育与休闲（sports） · vocab.html#t17-titre"},{"id":"q-vocab-b1-0035","level":"B1","skill":"vocab","prompt":"「Il a le cafard.」的意思是：","options":["他情绪低落","他精力充沛","他很害怕","他很生气"],"answer":"他情绪低落","explain":"avoir le cafard 是口语，意为心情沮丧；精力充沛是 plein d'énergie，害怕是 avoir peur，生气是 être en colère。","source":"词汇 · 十八、情感与态度（émotions） · vocab.html#t18-titre"},{"id":"q-vocab-b1-0036","level":"B1","skill":"vocab","prompt":"「s'énerver」的意思是：","options":["发火、急躁起来","鼓励别人","振作起来","冷静下来"],"answer":"发火、急躁起来","explain":"s'énerver 是发火、急躁；鼓励别人是 encourager，振作是 se ressaisir，冷静是 se calmer。","source":"词汇 · 十八、情感与态度（émotions） · vocab.html#t18-titre"},{"id":"q-vocab-b1-0037","level":"B1","skill":"vocab","prompt":"「faire grève」的意思是：","options":["罢工","做游戏","加班","请假"],"answer":"罢工","explain":"faire grève 是罢工（gréviste 是罢工者）；做游戏是 jouer，加班是 faire des heures supplémentaires，请假是 demander un congé。","source":"词汇 · 十九、社会与议题（société） · vocab.html#t19-titre"},{"id":"q-vocab-b1-0038","level":"B1","skill":"vocab","prompt":"「l'exclusion sociale」的意思是：","options":["社会排斥","社会阶层","社会保障","社会运动"],"answer":"社会排斥","explain":"exclusion 指被排斥在社会之外；社会阶层是 classe sociale，社会保障是 protection sociale，社会运动是 mouvement social。","source":"词汇 · 十九、社会与议题（société） · vocab.html#t19-titre"},{"id":"q-vocab-b1-0039","level":"B1","skill":"vocab","prompt":"「une espèce menacée」的意思是：","options":["濒危物种","外来物种","新发现物种","家养物种"],"answer":"濒危物种","explain":"menacée 意为受到威胁的；外来物种是 espèce invasive，新发现的物种是 espèce nouvellement découverte，家养物种是 espèce domestique。","source":"词汇 · 二十、环境与生态（environnement） · vocab.html#t20-titre"},{"id":"q-vocab-b1-0040","level":"B1","skill":"vocab","prompt":"「la pollution de l'air」的意思是：","options":["空气污染","水污染","噪音污染","土壤污染"],"answer":"空气污染","explain":"air 是空气；水污染是 pollution de l'eau，噪音污染是 pollution sonore，土壤污染是 pollution des sols。","source":"词汇 · 二十、环境与生态（environnement） · vocab.html#t20-titre"},{"id":"q-vocab-b1-0041","level":"B1","skill":"vocab","prompt":"在选举语境里，「les urnes」指：","options":["投票箱","议会席位","竞选海报","选票统计"],"answer":"投票箱","explain":"se rendre aux urnes 是去投票，urne 是投票箱；议会席位是 siège，竞选海报是 affiche électorale，选票统计是 dépouillement。","source":"词汇 · 二十一、政治与法律（politique et droit） · vocab.html#t21-titre"},{"id":"q-vocab-b1-0042","level":"B1","skill":"vocab","prompt":"「un témoin」的意思是：","options":["证人","律师","被告","陪审员"],"answer":"证人","explain":"témoin 是目击者、证人（témoigner 是作证）；律师是 avocat，被告是 accusé，陪审员是 juré。","source":"词汇 · 二十一、政治与法律（politique et droit） · vocab.html#t21-titre"},{"id":"q-vocab-b1-0043","level":"B1","skill":"vocab","prompt":"「le taux de chômage」的意思是：","options":["失业率","税率","增长率","利率"],"answer":"失业率","explain":"taux 是比率，chômage 是失业；税率是 taux d'imposition，增长率是 taux de croissance，利率是 taux d'intérêt。","source":"词汇 · 二十二、经济与金融（économie） · vocab.html#t22-titre"},{"id":"q-vocab-b1-0044","level":"B1","skill":"vocab","prompt":"「une pénurie de main-d'œuvre」的意思是：","options":["劳动力短缺","劳动力外流","通货膨胀","生产力下降"],"answer":"劳动力短缺","explain":"pénurie 是短缺，main-d'œuvre 是劳动力；人才外流是 fuite des cerveaux，通货膨胀是 inflation，生产力下降是 baisse de productivité。","source":"词汇 · 二十二、经济与金融（économie） · vocab.html#t22-titre"},{"id":"q-vocab-b1-0045","level":"B1","skill":"vocab","prompt":"「un chef-d'œuvre」的意思是：","options":["杰作","主要作品（未必最佳）","手工艺品","文学流派"],"answer":"杰作","explain":"chef-d'œuvre 指杰作、代表作；手工艺品是 artisanat，文学流派是 courant littéraire，主要作品应说 œuvre principale。","source":"词汇 · 二十三、文化与艺术（culture et arts） · vocab.html#t23-titre"},{"id":"q-vocab-b1-0046","level":"B1","skill":"vocab","prompt":"「Cette exposition a attiré les foules.」的意思是：","options":["这个展览吸引了大量观众","这个展览引起了争议","这个展览被取消了","这个展览门票很贵"],"answer":"这个展览吸引了大量观众","explain":"attirer les foules 指吸引大批人前来；引起争议是 susciter la polémique，被取消是 être annulée，门票贵是 être cher。","source":"词汇 · 二十三、文化与艺术（culture et arts） · vocab.html#t23-titre"}],"grammar":[{"id":"q-gram-b1-0001","level":"B1","skill":"grammar","prompt":"Il ___ donne le livre.（给我）","options":["me le","le me","me lui","le moi"],"answer":"me le","explain":"代词顺序固定为：me / te / nous / vous → le / la / les → lui / leur → y → en，所以是 il me le donne；le me 顺序颠倒，me lui 顺序错，le moi 用了重读代词且顺序错。","source":"语法点 · 代词顺序（l'ordre des pronoms） · grammar-a1a2.html#pro-ordre"},{"id":"q-gram-b1-0002","level":"B1","skill":"grammar","prompt":"Je ___ parlerai demain.（跟他谈这件事）","options":["lui en","en lui","lui le","le lui"],"answer":"lui en","explain":"顺序是 le / la / les 在 lui / leur 之前、y 在 en 之前，因此 lui + en 合法（je lui en parlerai）；en lui 顺序颠倒，lui le 顺序错，le lui 也是顺序错且语义不符。","source":"语法点 · 代词顺序（l'ordre des pronoms） · grammar-a1a2.html#pro-ordre"},{"id":"q-gram-b1-0003","level":"B1","skill":"grammar","prompt":"Donne-___ , s'il te plaît.（把它们给我）","options":["les-moi","moi-les","me-les","les me"],"answer":"les-moi","explain":"肯定命令式中直接宾语代词在前、间接宾语代词在后，且 me 要用重读形式 moi 并加连字符：donne-les-moi；moi-les 顺序颠倒，me-les 在肯定命令式里不能用 me，les me 缺连字符。","source":"语法点 · 代词顺序（l'ordre des pronoms） · grammar-a1a2.html#pro-ordre"},{"id":"q-gram-b1-0004","level":"B1","skill":"grammar","prompt":"Quand je suis arrivé, il ___ déjà parti.","options":["était","est","a été","sera"],"answer":"était","explain":"愈过去时表「过去的过去」：il était déjà parti；est 是现在时，a été parti 结构错误（être 不这样复合），sera 是将来时。","source":"语法点 · 愈过去时（le plus-que-parfait） · grammar-a1a2.html#plus-que-parfait"},{"id":"q-gram-b1-0005","level":"B1","skill":"grammar","prompt":"Elle a dit qu'elle ___ ce film avant.","options":["avait vu","a vu","verrait","voyait"],"answer":"avait vu","explain":"主句是过去时，从句动作更早，要用愈过去时 avait vu；a vu 未进行时态推移，verrait 表后时（过去将来），voyait 表同时。","source":"语法点 · 愈过去时（le plus-que-parfait） · grammar-a1a2.html#plus-que-parfait"},{"id":"q-gram-b1-0006","level":"B1","skill":"grammar","prompt":"Nous ___ tous les préparatifs avant que la fête commence.","options":["avions fini","avons fini","finissions","finirons"],"answer":"avions fini","explain":"主句动作先于 avant que 从句（从句用虚拟式），所以用愈过去时 avions fini；avons fini 缺时态推移，finissions 是未完成过去时，finirons 是将来时。","source":"语法点 · 愈过去时（le plus-que-parfait） · grammar-a1a2.html#plus-que-parfait"},{"id":"q-gram-b1-0007","level":"B1","skill":"grammar","prompt":"Il ___ quand soudain quelqu'un a frappé à la porte.（lire）","options":["lisait","a lu","lit","lira"],"answer":"lisait","explain":"未完成过去时铺背景，复合过去时 a frappé 推进事件；a lu 会变成另一个推进事件，lit 和 lira 与过去叙事的时间不符。","source":"语法点 · 叙事分工（les temps du récit） · grammar-b1b2.html#recit-pc-imp"},{"id":"q-gram-b1-0008","level":"B1","skill":"grammar","prompt":"Le soleil ___ et les oiseaux chantaient.","options":["brillait","a brillé","brille","brillera"],"answer":"brillait","explain":"场景描写用未完成过去时（与 chantaient 呼应）；a brillé 把描写当成一次性事件，brille 是现在时，brillera 是将来时。","source":"语法点 · 叙事分工（les temps du récit） · grammar-b1b2.html#recit-pc-imp"},{"id":"q-gram-b1-0009","level":"B1","skill":"grammar","prompt":"D'abord il ___ la porte, ensuite il ___ dans le salon.","options":["a ouvert / est entré","ouvrait / entrait","ouvre / entre","ouvrira / entrera"],"answer":"a ouvert / est entré","explain":"d'abord / ensuite 串联两个一次性动作，用复合过去时（entrer 用 être 且配合）；ouvrait / entrait 会把动作变成背景描写，现在时和将来时与叙事时间不符。","source":"语法点 · 叙事分工（les temps du récit） · grammar-b1b2.html#recit-pc-imp"},{"id":"q-gram-b1-0010","level":"B1","skill":"grammar","prompt":"Il m'a dit qu'il ___ à Paris le lendemain.","options":["partirait","partira","partait","est parti"],"answer":"partirait","explain":"主句过去时，从句表将来（le lendemain）要用条件式（过去将来）：partirait；partira 是现在时视角的将来，partait 表同时，est parti 表已完成。","source":"语法点 · 时态配合（la concordance des temps） · grammar-b1b2.html#concordance"},{"id":"q-gram-b1-0011","level":"B1","skill":"grammar","prompt":"Elle pensait que nous ___ raison.","options":["avions","avons","aurons","aurions"],"answer":"avions","explain":"主句过去时，从句表同时用未完成过去时：nous avions raison；avons 是现在时（未推移），aurons 和 aurions 表将来。","source":"语法点 · 时态配合（la concordance des temps） · grammar-b1b2.html#concordance"},{"id":"q-gram-b1-0012","level":"B1","skill":"grammar","prompt":"Je savais que tu ___ déjà ce livre.","options":["avais lu","as lu","lirais","lisais"],"answer":"avais lu","explain":"从句动作先于主句（déjà），用愈过去时 avais lu；as lu 未推移，lirais 表后时，lisais 表同时。","source":"语法点 · 时态配合（la concordance des temps） · grammar-b1b2.html#concordance"},{"id":"q-gram-b1-0013","level":"B1","skill":"grammar","prompt":"Paul a dit : « Je viendrai demain. » → Paul a dit qu'il ___ .","options":["viendrait le lendemain","viendra demain","venait hier","viendrait demain"],"answer":"viendrait le lendemain","explain":"间接引语四步同时调整：人称 je→il、时态将来→条件式、时间词 demain→le lendemain；三处任何一处没转换都不成立。","source":"语法点 · 间接引语四步转换（le discours indirect） · grammar-b1b2.html#di-regle"},{"id":"q-gram-b1-0014","level":"B1","skill":"grammar","prompt":"Marie m'a demandé : « Tu peux m'aider ? » → Marie m'a demandé si ___ .","options":["je pouvais l'aider","je peux m'aider","tu pouvais l'aider","je pourrais l'aider"],"answer":"je pouvais l'aider","explain":"一般疑问转述用 si + 陈述语序，同时 tu→je、m'→l'、现在时→未完成过去时；peux 未推移，tu 人称没转换，pourrais 时态不符（主句过去、动作同时应用未完成过去时）。","source":"语法点 · 间接引语四步转换（le discours indirect） · grammar-b1b2.html#di-regle"},{"id":"q-gram-b1-0015","level":"B1","skill":"grammar","prompt":"Il a expliqué : « J'ai fini mon travail. » → Il a expliqué qu'il ___ son travail.","options":["avait fini","a fini","finissait","finirait"],"answer":"avait fini","explain":"复合过去时在间接引语中推移为愈过去时：avait fini；a fini 未推移，finissait 对应未完成过去时，finirait 对应将来时。","source":"语法点 · 间接引语时态推移（la transposition des temps） · grammar-b1b2.html#di-temps"},{"id":"q-gram-b1-0016","level":"B1","skill":"grammar","prompt":"Elle a dit : « Je partirai tôt. » → Elle a dit qu'elle ___ tôt.","options":["partirait","partira","partait","est partie"],"answer":"partirait","explain":"简单将来时推移为条件式现在时 partirait；partira 未推移，partait 对应未完成过去时，est partie 对应复合过去时。","source":"语法点 · 间接引语时态推移（la transposition des temps） · grammar-b1b2.html#di-temps"},{"id":"q-gram-b1-0017","level":"B1","skill":"grammar","prompt":"Il a raconté : « Nous étions en retard. » → Il a raconté qu'ils ___ en retard.","options":["étaient","sont","seraient","avaient été"],"answer":"étaient","explain":"未完成过去时在间接引语中保持不变：étaient；sont 未推移，seraient 对应将来时，avaient été 对应愈过去时（原句并非愈过去时）。","source":"语法点 · 间接引语时态推移（la transposition des temps） · grammar-b1b2.html#di-temps"},{"id":"q-gram-b1-0018","level":"B1","skill":"grammar","prompt":"Il a dit : « Je te verrai demain. » → Il a dit qu'il me verrait ___ .","options":["le lendemain","demain","la veille","ce jour-là"],"answer":"le lendemain","explain":"demain 推移为 le lendemain；demain 未推移，la veille 对应 hier，ce jour-là 对应 aujourd'hui。","source":"语法点 · 间接引语时间地点词（le déplacement des repères） · grammar-b1b2.html#di-mots"},{"id":"q-gram-b1-0019","level":"B1","skill":"grammar","prompt":"Elle a raconté : « Hier, j'ai vu Paul. » → Elle a raconté qu'elle avait vu Paul ___ .","options":["la veille","hier","le lendemain","ce jour-là"],"answer":"la veille","explain":"hier 推移为 la veille；hier 未推移，le lendemain 对应 demain，ce jour-là 对应 aujourd'hui。","source":"语法点 · 间接引语时间地点词（le déplacement des repères） · grammar-b1b2.html#di-mots"},{"id":"q-gram-b1-0020","level":"B1","skill":"grammar","prompt":"Il a demandé : « Où vas-tu maintenant ? » → Il a demandé où j'allais ___ .","options":["à ce moment-là","maintenant","le jour suivant","la veille"],"answer":"à ce moment-là","explain":"maintenant 推移为 à ce moment-là；maintenant 未推移，le jour suivant 对应 demain，la veille 对应 hier。","source":"语法点 · 间接引语时间地点词（le déplacement des repères） · grammar-b1b2.html#di-mots"},{"id":"q-gram-b1-0021","level":"B1","skill":"grammar","prompt":"Il m'a demandé : « Quelle heure est-il ? » → Il m'a demandé ___ .","options":["quelle heure il était","quelle heure est-il","si quelle heure il était","quelle heure était-il"],"answer":"quelle heure il était","explain":"特殊疑问转述保留疑问词，但必须改成陈述语序并推移时态：quelle heure il était；est-il 仍是直接疑问倒装，si 只用于一般疑问，était-il 语序未改。","source":"语法点 · 疑问与命令的转述（la question indirecte） · grammar-b1b2.html#di-question"},{"id":"q-gram-b1-0022","level":"B1","skill":"grammar","prompt":"Elle a demandé : « Viens-tu avec nous ? » → Elle a demandé ___ .","options":["si je venais avec eux","si je viens avec vous","que je venais avec eux","si venais-je avec eux"],"answer":"si je venais avec eux","explain":"一般疑问用 si + 陈述语序，并且 tu→je、nous→eux、现在时→未完成过去时：si je venais avec eux；后三项分别是人称时态未转换、连接词错误和保留倒装。","source":"语法点 · 疑问与命令的转述（la question indirecte） · grammar-b1b2.html#di-question"},{"id":"q-gram-b1-0023","level":"B1","skill":"grammar","prompt":"Le professeur nous a dit : « Fermez vos livres ! » → Le professeur nous a dit ___ .","options":["de fermer nos livres","de fermer vos livres","que nous fermions nos livres","fermez nos livres"],"answer":"de fermer nos livres","explain":"命令转述用 de + 不定式，人称 vos→nos：de fermer nos livres；vos livres 人称未转换，que + 虚拟式不是命令转述的常规形式，直接保留命令句没有转述。","source":"语法点 · 疑问与命令的转述（la question indirecte） · grammar-b1b2.html#di-question"},{"id":"q-gram-b1-0024","level":"B1","skill":"grammar","prompt":"Il faut que tu ___ .（venir）","options":["viennes","viens","viendras","venais"],"answer":"viennes","explain":"il faut que 触发虚拟式现在时，venir 取 ils viennent 的词干 vienn- 加 -es：viennes；viens 是直陈式现在时，viendras 是将来时，venais 是未完成过去时。","source":"语法点 · 虚拟式现在时（le subjonctif présent） · grammar-b1b2.html#subj-formation"},{"id":"q-gram-b1-0025","level":"B1","skill":"grammar","prompt":"Je veux que vous ___ prêts.（être）","options":["soyez","êtes","serez","étiez"],"answer":"soyez","explain":"vouloir que 触发虚拟式，être 的虚拟式为 sois / sois / soit / soyons / soyez / soient，vous 用 soyez；êtes、serez、étiez 都是直陈式。","source":"语法点 · 虚拟式现在时（le subjonctif présent） · grammar-b1b2.html#subj-formation"},{"id":"q-gram-b1-0026","level":"B1","skill":"grammar","prompt":"Il est important que nous ___ ce dossier.（finir）","options":["finissions","finissons","finirons","finir"],"answer":"finissions","explain":"无人称表达 il est important que 触发虚拟式，nous 形式以 -issions 结尾（finissions）；finissons 是直陈式现在时，finirons 是将来时，finir 是原形。","source":"语法点 · 虚拟式现在时（le subjonctif présent） · grammar-b1b2.html#subj-formation"},{"id":"q-gram-b1-0027","level":"B1","skill":"grammar","prompt":"Bien qu'il ___ fatigué, il continue à travailler.（être）","options":["soit","est","sera","était"],"answer":"soit","explain":"bien que 引导让步从句必须用虚拟式：soit；est、sera、était 都是直陈式，不能用于 bien que 之后。","source":"语法点 · 虚拟式现在时（le subjonctif présent） · grammar-b1b2.html#subj-formation"},{"id":"q-gram-b1-0028","level":"B1","skill":"grammar","prompt":"Je doute qu'il ___ la vérité.（dire）","options":["dise","dit","dira","disait"],"answer":"dise","explain":"douter que 表怀疑，触发虚拟式：dise；dit 是直陈式现在时，dira 是将来时，disait 是未完成过去时。","source":"语法点 · 虚拟式触发词（les déclencheurs du subjonctif） · grammar-b1b2.html#subj-declencheurs"},{"id":"q-gram-b1-0029","level":"B1","skill":"grammar","prompt":"Je pense qu'il ___ raison.（肯定句）","options":["a","ait","aura","avait"],"answer":"a","explain":"penser 的肯定句用直陈式：je pense qu'il a raison；只有否定句和疑问句（je ne pense pas qu'il ait…）才改用虚拟式，aura 和 avait 也与时态不符。","source":"语法点 · 虚拟式触发词（les déclencheurs du subjonctif） · grammar-b1b2.html#subj-declencheurs"},{"id":"q-gram-b1-0030","level":"B1","skill":"grammar","prompt":"Je ne pense pas qu'il ___ raison.（否定句）","options":["ait","a","aura","avait"],"answer":"ait","explain":"penser 的否定形式触发虚拟式：je ne pense pas qu'il ait raison；a 是直陈式（只用于肯定），aura 和 avait 的语式与时态都不符。","source":"语法点 · 虚拟式触发词（les déclencheurs du subjonctif） · grammar-b1b2.html#subj-declencheurs"},{"id":"q-gram-b1-0031","level":"B1","skill":"grammar","prompt":"Il est nécessaire que vous ___ ce formulaire.（remplir）","options":["remplissiez","remplissez","remplirez","remplir"],"answer":"remplissiez","explain":"il est nécessaire que 触发虚拟式，vous 形式词尾为 -issiez：remplissiez；remplissez 是直陈式现在时，remplirez 是将来时，remplir 是原形。","source":"语法点 · 虚拟式触发词（les déclencheurs du subjonctif） · grammar-b1b2.html#subj-declencheurs"},{"id":"q-gram-b1-0032","level":"B1","skill":"grammar","prompt":"À ta place, je ___ ce poste.（accepter）","options":["accepterais","accepterai","accepte","acceptais"],"answer":"accepterais","explain":"à ta place 表假设（「换成我就……」），主句用条件式现在时；accepterai 是将来时，accepte 是现在时，acceptais 是未完成过去时。","source":"语法点 · 条件式现在时用法（le conditionnel présent） · grammar-b1b2.html#cond-usage"},{"id":"q-gram-b1-0033","level":"B1","skill":"grammar","prompt":"Selon la presse, le ministre ___ démissionné.","options":["aurait","aura","a","avait"],"answer":"aurait","explain":"条件式可表未经证实的传闻（「据报」）：aurait démissionné；aura 是将来时，a 是现在时，avait 是未完成过去时，都表达不出这种存疑语气。","source":"语法点 · 条件式现在时用法（le conditionnel présent） · grammar-b1b2.html#cond-usage"},{"id":"q-gram-b1-0034","level":"B1","skill":"grammar","prompt":"Ce ___ être une erreur.（委婉推测）","options":["serait","sera","est","était"],"answer":"serait","explain":"条件式表推测和委婉：ce serait une erreur；sera 是将来时，est 是现在时，était 是过去时，都缺少委婉推测的语气。","source":"语法点 · 条件式现在时用法（le conditionnel présent） · grammar-b1b2.html#cond-usage"},{"id":"q-gram-b1-0035","level":"B1","skill":"grammar","prompt":"Si tu ___ , tu réussiras.（travailler）","options":["travailles","travailleras","travaillais","travaillerais"],"answer":"travailles","explain":"第一型真实假设：si + 现在时，主句用将来时；si 从句中不能用将来时，travailleras 是中国人最常犯的错误，travaillais / travaillerais 属第二型非现实假设。","source":"语法点 · si 三种假设句型（les trois systèmes hypothétiques） · grammar-b1b2.html#si-trois"},{"id":"q-gram-b1-0036","level":"B1","skill":"grammar","prompt":"Si j'étais toi, je ___ tout de suite.（partir）","options":["partirais","partirai","pars","partais"],"answer":"partirais","explain":"第二型非现实假设：si + 未完成过去时，主句用条件式现在时；partirai 是将来时，pars 是现在时，partais 是未完成过去时（主句不能再用）。","source":"语法点 · si 三种假设句型（les trois systèmes hypothétiques） · grammar-b1b2.html#si-trois"},{"id":"q-gram-b1-0037","level":"B1","skill":"grammar","prompt":"Si elle avait étudié, elle ___ l'examen.（réussir）","options":["aurait réussi","réussirait","avait réussi","réussissait"],"answer":"aurait réussi","explain":"第三型未实现的过去假设：si + 愈过去时，主句用条件式过去时；réussirait 是条件式现在时，avait réussi 是愈过去时（不能再作主句），réussissait 是未完成过去时。","source":"语法点 · si 三种假设句型（les trois systèmes hypothétiques） · grammar-b1b2.html#si-trois"},{"id":"q-gram-b1-0038","level":"B1","skill":"grammar","prompt":"Si j'avais su, je ___ autrement.（agir）","options":["aurais agi","agirais","agissais","ai agi"],"answer":"aurais agi","explain":"与过去事实相反：si + 愈过去时（avais su）配主句条件式过去时 aurais agi；agirais 是条件式现在时（只配 si + 未完成过去时），agissais 是未完成过去时，ai agi 是复合过去时。","source":"语法点 · si 三种假设句型（les trois systèmes hypothétiques） · grammar-b1b2.html#si-trois"},{"id":"q-gram-b1-0039","level":"B1","skill":"grammar","prompt":"Le rapport ___ par le directeur hier.（écrire）","options":["a été écrit","a écrit","est écrit","était écrit"],"answer":"a été écrit","explain":"被动态＝être（体现时态）+ 过去分词（配合）+ par 施动者，这里时间词是 hier，所以用复合过去时被动态 a été écrit；a écrit 是主动且缺宾语，est écrit 是现在时，était écrit 是未完成过去时。","source":"语法点 · 被动态构成（la voix passive） · grammar-b1b2.html#passif-formation"},{"id":"q-gram-b1-0040","level":"B1","skill":"grammar","prompt":"Cette maison ___ en 1900.（construire）","options":["a été construite","a construit","est construit","a été construites"],"answer":"a été construite","explain":"maison 是阴性单数，过去分词配合加 -e：a été construite；a construit 缺被动态，est construit 是现在时且缺配合，construites 复数配合错误。","source":"语法点 · 被动态构成（la voix passive） · grammar-b1b2.html#passif-formation"},{"id":"q-gram-b1-0041","level":"B1","skill":"grammar","prompt":"Les volets sont fermés ___ le gardien chaque soir.","options":["par","de","à","pour"],"answer":"par","explain":"被动态的动作施动者用 par：fermés par le gardien；de 用于情感或状态类动词（aimé de ses parents）或表示状态，à 和 pour 不能引导施动者。","source":"语法点 · 被动态构成（la voix passive） · grammar-b1b2.html#passif-formation"},{"id":"q-gram-b1-0042","level":"B1","skill":"grammar","prompt":"C'est Paul ___ a cassé le vase.","options":["qui","que","dont","où"],"answer":"qui","explain":"被强调成分 Paul 在从句中作主语，用 c'est…qui；que 用于被强调成分作宾语或状语，dont 替代 de + 名词，où 表时间或地点。","source":"语法点 · 强调结构 c'est…qui / que（la mise en relief） · grammar-b1b2.html#mer-cest"},{"id":"q-gram-b1-0043","level":"B1","skill":"grammar","prompt":"C'est ce livre ___ je préfère.","options":["que","qui","dont","où"],"answer":"que","explain":"被强调成分 ce livre 在从句中作直接宾语，用 que；qui 只用于主语，dont 替代 de + 名词，où 表时间地点。","source":"语法点 · 强调结构 c'est…qui / que（la mise en relief） · grammar-b1b2.html#mer-cest"},{"id":"q-gram-b1-0044","level":"B1","skill":"grammar","prompt":"C'est à Paris ___ il fait ses études.","options":["que","qui","dont","où"],"answer":"que","explain":"被强调成分 à Paris 是地点状语，强调结构仍用 que（c'est…que），不能再用 où；qui 只用于被强调成分作主语，dont 替代 de + 名词。","source":"语法点 · 强调结构 c'est…qui / que（la mise en relief） · grammar-b1b2.html#mer-cest"},{"id":"q-gram-b1-0045","level":"B1","skill":"grammar","prompt":"Attends, je ___ t'aider.（当场决定）","options":["vais","irai","irais","allais"],"answer":"vais","explain":"当场决定、马上要做的动作用最近将来时 aller + 不定式；irai 是简单将来时（多用于较远的计划或承诺），irais 是条件式，allais 是未完成过去时。","source":"语法点 · 三种「将来」的语体差别（aller + inf. / futur simple / présent） · grammar-a1a2.html#avenir-styles"},{"id":"q-gram-b1-0046","level":"B1","skill":"grammar","prompt":"Le train ___ à 8 heures demain matin.（时刻表）","options":["part","partira","va partir","partirait"],"answer":"part","explain":"固定的时刻表、日程用现在时表将来：le train part à 8 heures；partira 语式偏「预计/承诺」，va partir 强调眼前马上出发，partirait 是条件式。","source":"语法点 · 三种「将来」的语体差别（aller + inf. / futur simple / présent） · grammar-a1a2.html#avenir-styles"},{"id":"q-gram-b1-0047","level":"B1","skill":"grammar","prompt":"Il n'est pas venu ___ il était malade.","options":["parce qu'","à cause","grâce à","donc"],"answer":"parce qu'","explain":"引导原因从句用 parce que，元音前省音为 parce qu'；à cause de 和 grâce à 后只能接名词（分别表消极与积极原因），donc 表结果。","source":"语法点 · 原因连接词（l'expression de la cause） · grammar-b1b2.html#conn-cause"},{"id":"q-gram-b1-0048","level":"B1","skill":"grammar","prompt":"___ tu es là, aide-moi à porter les cartons !","options":["Puisque","Pourtant","Donc","À cause de"],"answer":"Puisque","explain":"puisque 表「既然」（已知、双方共知的原因），可以放在句首引导原因：Puisque tu es là…；pourtant 表转折，donc 表结果，à cause de 后只能接名词，都不能引导这个原因从句。","source":"语法点 · 原因连接词（l'expression de la cause） · grammar-b1b2.html#conn-cause"},{"id":"q-gram-b1-0049","level":"B1","skill":"grammar","prompt":"Le match a été annulé ___ la pluie.","options":["à cause de","parce que","grâce à","donc"],"answer":"à cause de","explain":"后接名词、表消极原因用 à cause de；parce que 后接从句，grâce à 表积极的「多亏」，donc 表结果。","source":"语法点 · 原因连接词（l'expression de la cause） · grammar-b1b2.html#conn-cause"},{"id":"q-gram-b1-0050","level":"B1","skill":"grammar","prompt":"Il pleuvait, ___ nous avons annulé le pique-nique.","options":["donc","parce que","pourtant","comme"],"answer":"donc","explain":"前后是「因为下雨所以取消」的结果关系，用 donc；parce que 和 comme 表原因，pourtant 表转折。","source":"语法点 · 结果连接词（l'expression de la conséquence） · grammar-b1b2.html#conn-consequence"},{"id":"q-gram-b1-0051","level":"B1","skill":"grammar","prompt":"Il a tellement travaillé ___ il est tombé malade.","options":["qu'","que","dont","si"],"answer":"qu'","explain":"tellement…que 引出结果从句，que 在元音 il 前必须省音为 qu'；写 que 是拼写错误，dont 替代 de + 名词，si 不能引导结果从句。","source":"语法点 · 结果连接词（l'expression de la conséquence） · grammar-b1b2.html#conn-consequence"},{"id":"q-gram-b1-0052","level":"B1","skill":"grammar","prompt":"La route était si glissante ___ plusieurs voitures sont sorties de la route.","options":["que","qu'","dont","comme"],"answer":"que","explain":"si + 形容词 + que 引出结果从句，que 后的词以辅音开头时不省音；qu' 只在元音或哑音 h 前使用，dont 替代 de + 名词，comme 表原因。","source":"语法点 · 结果连接词（l'expression de la conséquence） · grammar-b1b2.html#conn-consequence"},{"id":"q-gram-b1-0053","level":"B1","skill":"grammar","prompt":"Je t'explique ___ tu comprennes.","options":["pour que","pour","parce que","donc"],"answer":"pour que","explain":"主从句主语不同（je / tu），目的用 pour que + 虚拟式；pour 后只能接不定式（主语须相同），parce que 表原因，donc 表结果。","source":"语法点 · 目的连接词（l'expression du but） · grammar-b1b2.html#conn-but"},{"id":"q-gram-b1-0054","level":"B1","skill":"grammar","prompt":"Il travaille beaucoup ___ réussir son examen.","options":["pour","pour que","afin qu'","parce que"],"answer":"pour","explain":"主从句主语相同（il / il），目的用 pour + 不定式；pour que 和 afin que 后面必须接从句，parce que 表原因。","source":"语法点 · 目的连接词（l'expression du but） · grammar-b1b2.html#conn-but"},{"id":"q-gram-b1-0055","level":"B1","skill":"grammar","prompt":"Elle parle lentement ___ tout le monde la comprenne.","options":["pour que","pour","afin de","à cause de"],"answer":"pour que","explain":"两个主语不同（elle / tout le monde），用 pour que + 虚拟式；pour 和 afin de 后接不定式（要求主语一致），à cause de 后接名词且表原因。","source":"语法点 · 目的连接词（l'expression du but） · grammar-b1b2.html#conn-but"},{"id":"q-gram-b1-0056","level":"B1","skill":"grammar","prompt":"___ je lisais, le téléphone a sonné.","options":["Pendant que","Depuis que","Avant que","Jusqu'à ce que"],"answer":"Pendant que","explain":"两个动作同时进行用 pendant que + 直陈式；depuis que 表「自从」（延续到现在），avant que 和 jusqu'à ce que 都要接虚拟式并且语义不符。","source":"语法点 · 时间连接词（l'expression du temps） · grammar-b1b2.html#conn-temps"},{"id":"q-gram-b1-0057","level":"B1","skill":"grammar","prompt":"Préviens-moi ___ tu partes.","options":["avant que","avant de","pendant que","dès"],"answer":"avant que","explain":"两个主语不同（tu / moi）时「在……之前」用 avant que + 虚拟式；avant de 后接不定式（要求主语一致），pendant que 表同时，dès 不能单独引导这个从句。","source":"语法点 · 时间连接词（l'expression du temps） · grammar-b1b2.html#conn-temps"},{"id":"q-gram-b1-0058","level":"B1","skill":"grammar","prompt":"___ il est arrivé, il a tout de suite téléphoné à sa mère.","options":["Dès qu'","Dès que","Depuis qu'","Pendant qu'"],"answer":"Dès qu'","explain":"dès que 表「一……就……」，que 在元音 il 前省音为 qu'；Dès que il 缺省音，depuis que 表「自从」并延续到现在，pendant que 表同时。","source":"语法点 · 时间连接词（l'expression du temps） · grammar-b1b2.html#conn-temps"}],"listening":[{"id":"q-listen-b1-0001","level":"B1","skill":"listening","prompt":"[听力原文] Si j'avais plus de temps, je ferais du sport trois fois par semaine. Malheureusement, mon travail me prend soixante heures par semaine. 问题：Pourquoi ne fait-elle pas de sport ?","options":["Parce qu'elle manque de temps","Parce qu'elle n'aime pas le sport","Parce qu'elle est malade","Parce que la salle de sport est fermée"],"answer":"Parce qu'elle manque de temps","explain":"si j'avais plus de temps 是与事实相反的假设，说明真正原因是没时间；不喜欢、生病、场馆关门都没有提到。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0002","level":"B1","skill":"listening","prompt":"[听力原文] Le maire a annoncé qu'un nouveau parc serait construit avant la fin de l'année. 问题：Qu'a annoncé le maire ?","options":["La construction d'un parc avant la fin de l'année","La fermeture d'un parc","La construction d'une école","Une hausse des impôts"],"answer":"La construction d'un parc avant la fin de l'année","explain":"间接引语里用条件式 serait construit 表将来的计划；école 和 impôts 没有出现，fermeture 与 construire 相反。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0003","level":"B1","skill":"listening","prompt":"[听力原文] Bien que le prix des logements augmente, beaucoup de jeunes continuent à s'installer dans le centre-ville. 问题：Que font beaucoup de jeunes ?","options":["Ils continuent à s'installer dans le centre-ville","Ils quittent le centre-ville","Ils achètent une maison à la campagne","Ils attendent une baisse des prix"],"answer":"Ils continuent à s'installer dans le centre-ville","explain":"bien que 引导让步从句，主句才是信息重点：continuent à s'installer dans le centre-ville；其余选项与主句相反或没有依据。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0004","level":"B1","skill":"listening","prompt":"[听力原文] — Tu aurais dû me prévenir plus tôt ! — Désolé, je n'ai pas eu ton message. 问题：Quel est le reproche fait à l'autre personne ?","options":["Elle aurait dû prévenir plus tôt","Elle est arrivée en retard","Elle a perdu son téléphone","Elle a oublié la réunion"],"answer":"Elle aurait dû prévenir plus tôt","explain":"条件式过去时 tu aurais dû 表责备（「你本该早告诉我」）；迟到、丢手机、忘记开会都不是原话内容。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0005","level":"B1","skill":"listening","prompt":"[听力原文] Cette entreprise cherche à réduire ses coûts afin de rester compétitive sur le marché européen. 问题：Pourquoi cherche-t-elle à réduire ses coûts ?","options":["Pour rester compétitive","Pour embaucher davantage","Pour ouvrir une nouvelle usine","Pour augmenter les salaires"],"answer":"Pour rester compétitive","explain":"afin de + 不定式表目的：rester compétitive；招聘、开厂、加薪都不是原文的目的。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0006","level":"B1","skill":"listening","prompt":"[听力原文] Je ne pense pas que cette solution soit réaliste, même si elle paraît séduisante. 问题：Quelle est son opinion sur cette solution ?","options":["Elle n'est pas réaliste","Elle est excellente","Elle est trop chère","Elle est déjà appliquée"],"answer":"Elle n'est pas réaliste","explain":"je ne pense pas que 后用虚拟式 soit，表否定判断；même si elle paraît séduisante 只是让步，不能推翻主句判断。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0007","level":"B1","skill":"listening","prompt":"[听力原文] Quand je suis arrivé à la gare, le train était déjà parti depuis dix minutes. 问题：Que s'est-il passé ?","options":["Le train était déjà parti","Il a pris le train","Le train avait du retard","Il a attendu le train suivant"],"answer":"Le train était déjà parti","explain":"愈过去时 était déjà parti depuis dix minutes 表示「我到之前车已开走十分钟」；晚点与等下一班车都没有提到。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0008","level":"B1","skill":"listening","prompt":"[听力原文] Le gouvernement a décidé d'interdire la circulation des voitures les plus polluantes dans le centre-ville à partir de 2026. 问题：Que décide le gouvernement ?","options":["Interdire les voitures les plus polluantes au centre-ville","Interdire toutes les voitures","Construire des parkings","Baisser le prix de l'essence"],"answer":"Interdire les voitures les plus polluantes au centre-ville","explain":"限定语 les plus polluantes（污染最严重的）是关键，不是禁止所有汽车；parkings 和 essence 在原文没有出现。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0009","level":"B1","skill":"listening","prompt":"[听力原文] — Vous avez des questions sur le contrat ? — Oui, je voudrais savoir si je peux travailler à distance deux jours par semaine. 问题：Que veut savoir l'employé ?","options":["S'il peut télétravailler deux jours par semaine","S'il peut partir en vacances","Combien il sera payé","Quand commence le contrat"],"answer":"S'il peut télétravailler deux jours par semaine","explain":"间接疑问 si je peux travailler à distance deux jours par semaine 是核心问题；其他三项原文没有提到。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0010","level":"B1","skill":"listening","prompt":"[听力原文] L'enquête montre que les jeunes lisent moins de livres qu'avant, mais qu'ils lisent davantage sur écran. 问题：Que montre l'enquête ?","options":["Les jeunes lisent moins de livres et plus sur écran","Les jeunes ne lisent plus du tout","Les jeunes lisent plus de livres","Les jeunes préfèrent les bibliothèques"],"answer":"Les jeunes lisent moins de livres et plus sur écran","explain":"moins de livres 与 davantage sur écran 要合起来抓；「完全不读」和「读更多书」都是过度或反向解读。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0011","level":"B1","skill":"listening","prompt":"[听力原文] Malgré la fatigue, elle a terminé son rapport avant la réunion. 问题：Qu'a-t-elle fait ?","options":["Elle a fini son rapport avant la réunion","Elle a reporté la réunion","Elle n'a pas fini son rapport","Elle a demandé de l'aide"],"answer":"Elle a fini son rapport avant la réunion","explain":"malgré la fatigue 是让步，主句 a terminé son rapport avant la réunion 才是事实；reporté、pas fini 都与原意矛盾。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0012","level":"B1","skill":"listening","prompt":"[听力原文] Je t'appellerai dès que j'aurai les résultats de l'analyse. 问题：Quand va-t-il appeler ?","options":["Dès qu'il aura les résultats","Avant l'analyse","Dans une semaine exactement","Il ne va pas appeler"],"answer":"Dès qu'il aura les résultats","explain":"dès que + 将来完成时（j'aurai）表示「一拿到结果就打电话」；其他选项把条件与时间关系弄错。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0013","level":"B1","skill":"listening","prompt":"[听力原文] La réunion a été annulée en raison de l'absence du directeur. 问题：Pourquoi la réunion a-t-elle été annulée ?","options":["À cause de l'absence du directeur","À cause d'une grève","Par manque de salle","Parce qu'il y avait trop de participants"],"answer":"À cause de l'absence du directeur","explain":"en raison de 表原因，对应 l'absence du directeur；grève、salle、participants 都没有出现。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0014","level":"B1","skill":"listening","prompt":"[听力原文] Ce qui m'inquiète, ce n'est pas le coût du projet, mais le temps qu'il faudra pour le réaliser. 问题：Qu'est-ce qui l'inquiète ?","options":["Le temps nécessaire pour réaliser le projet","Le coût du projet","Le nombre de participants","La qualité des matériaux"],"answer":"Le temps nécessaire pour réaliser le projet","explain":"强调结构 ce n'est pas… mais… 把重点放在 le temps；coût 是被明确排除的项。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0015","level":"B1","skill":"listening","prompt":"[听力原文] Elle a réussi son examen bien qu'elle ait travaillé à temps partiel pendant toute l'année. 问题：Que dit-on d'elle ?","options":["Elle a réussi malgré son travail à temps partiel","Elle a échoué à l'examen","Elle n'a pas travaillé","Elle a abandonné ses études"],"answer":"Elle a réussi malgré son travail à temps partiel","explain":"bien qu'elle ait travaillé（虚拟式让步）与主句 a réussi 并存；échoué、pas travaillé、abandonné 都与原意相反。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0016","level":"B1","skill":"listening","prompt":"[听力原文] Avant de partir, nous devons vérifier que toutes les fenêtres sont fermées. 问题：Que doivent-ils faire avant de partir ?","options":["Vérifier que les fenêtres sont fermées","Fermer la porte d'entrée","Éteindre le chauffage","Prévenir le voisin"],"answer":"Vérifier que les fenêtres sont fermées","explain":"原文是 vérifier que toutes les fenêtres sont fermées；门、暖气、邻居都是同类干扰，不在原话里。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0017","level":"B1","skill":"listening","prompt":"[听力原文] Le nombre de visiteurs a augmenté de vingt pour cent par rapport à l'année dernière. 问题：Quelle est l'évolution du nombre de visiteurs ?","options":["Il a augmenté de 20 %","Il a baissé de 20 %","Il est resté stable","Il a doublé"],"answer":"Il a augmenté de 20 %","explain":"augmenter de vingt pour cent 是增长 20%；baisser 是反义，doubler 是翻倍（100%），stable 与原文矛盾。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"},{"id":"q-listen-b1-0018","level":"B1","skill":"listening","prompt":"[听力原文] Je préfère te prévenir tout de suite : je ne pourrai pas venir à ton mariage, je serai en déplacement à l'étranger. 问题：Pourquoi ne pourra-t-il pas venir au mariage ?","options":["Il sera en déplacement à l'étranger","Il n'aime pas les mariages","Il n'a pas reçu l'invitation","Il travaillera dans sa ville ce jour-là"],"answer":"Il sera en déplacement à l'étranger","explain":"原因明确是 en déplacement à l'étranger；没收到邀请、不喜欢、本地上班都是原文没有的推测。","source":"听力 · B1 访谈与公告（compréhension orale B1 · DELF）"}],"reading":[{"id":"q-read-b1-0001","level":"B1","skill":"reading","prompt":"[阅读] Selon une étude récente, les Français passent en moyenne trois heures par jour devant un écran. Ce chiffre augmente surtout chez les 18-25 ans. 问题：Chez quel public ce chiffre augmente-t-il le plus ?","options":["Chez les 18-25 ans","Chez les retraités","Chez les enfants","Chez les 40-50 ans"],"answer":"Chez les 18-25 ans","explain":"原文说 augmente surtout chez les 18-25 ans；其他年龄段并没有被指为增长最快。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0002","level":"B1","skill":"reading","prompt":"[阅读] La mairie a décidé d'interdire les voitures les plus polluantes dans le centre à partir de 2026, afin de réduire la pollution de l'air. 问题：Pourquoi la mairie prend-elle cette mesure ?","options":["Pour réduire la pollution","Pour augmenter les recettes","Pour limiter le stationnement","Pour favoriser le tourisme"],"answer":"Pour réduire la pollution","explain":"afin de + 不定式表目的：réduire la pollution de l'air；财政收入、停车限制、旅游都不是原文理由。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0003","level":"B1","skill":"reading","prompt":"[阅读] Bien que le télétravail séduise de nombreux salariés, certains employeurs craignent une baisse de la cohésion d'équipe. 问题：Que craignent certains employeurs ?","options":["Une baisse de la cohésion d'équipe","Une hausse des salaires","Une pénurie de bureaux","La fermeture des entreprises"],"answer":"Une baisse de la cohésion d'équipe","explain":"bien que 引导让步从句，主句 craignent 的宾语是 baisse de la cohésion d'équipe；其他都不是担心的对象。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0004","level":"B1","skill":"reading","prompt":"[阅读] Le maire a annoncé que la nouvelle ligne de tramway serait mise en service avant la fin du mandat. 问题：Qu'a annoncé le maire ?","options":["La mise en service d'une ligne de tramway","La fermeture d'une ligne","La construction d'un aéroport","Une hausse des impôts locaux"],"answer":"La mise en service d'une ligne de tramway","explain":"间接引语里的条件式 serait 表将来计划，内容是新电车线投入使用；其余选项与原文无关。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0005","level":"B1","skill":"reading","prompt":"[阅读] Cette association recueille des dons pour financer des repas gratuits destinés aux étudiants en difficulté. 问题：À quoi servent les dons ?","options":["À financer des repas gratuits pour des étudiants","À construire des logements","À payer des professeurs","À acheter des ordinateurs"],"answer":"À financer des repas gratuits pour des étudiants","explain":"目的在 pour financer… destinés aux étudiants；住宿、教师、电脑都没有出现。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0006","level":"B1","skill":"reading","prompt":"[阅读] Il faut que les candidats déposent leur dossier avant le 15 mars ; aucune candidature ne sera acceptée après cette date. 问题：Quelle est la date limite de dépôt ?","options":["Le 15 mars","Le 15 mai","Le 5 mars","Il n'y a pas de limite"],"answer":"Le 15 mars","explain":"avant le 15 mars 是截止日，过期不再受理；mai 是月份混淆，5 mars 是数字调换。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0007","level":"B1","skill":"reading","prompt":"[阅读] Si les habitants avaient été consultés, le projet aurait sans doute été modifié. 问题：Que suggère l'auteur ?","options":["Le projet aurait pu être modifié si on avait consulté les habitants","Le projet a été modifié","Les habitants ont refusé le projet","Le projet est parfait"],"answer":"Le projet aurait pu être modifié si on avait consulté les habitants","explain":"si + 愈过去时（avaient été consultés）配主句条件式过去时（aurait été modifié）表未实现的假设：居民没被征询，项目也没改。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0008","level":"B1","skill":"reading","prompt":"[阅读] Les prix des logements ont augmenté de 8 % en un an, alors que les salaires stagnent. 问题：Que dit l'article ?","options":["Les prix augmentent alors que les salaires stagnent","Les salaires augmentent plus vite","Les prix baissent","Tout augmente au même rythme"],"answer":"Les prix augmentent alors que les salaires stagnent","explain":"alors que 表对比：房价涨 8%，工资停滞；其余选项把对比关系弄反或抹平。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0009","level":"B1","skill":"reading","prompt":"[阅读] Le directeur exige que chaque employé suive une formation en informatique avant la fin de l'année. 问题：Que doit faire chaque employé ?","options":["Suivre une formation en informatique","Changer de service","Travailler le week-end","Passer un examen de langue"],"answer":"Suivre une formation en informatique","explain":"exiger que + 虚拟式（suive）：年底前参加信息技术培训；其他都不是要求内容。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0010","level":"B1","skill":"reading","prompt":"[阅读] Ce roman raconte l'histoire d'une famille qui quitte son village pour s'installer en ville, et les difficultés qu'elle rencontre. 问题：De quoi parle ce roman ?","options":["D'une famille qui s'installe en ville","D'un village abandonné","D'un voyage à l'étranger","D'une histoire d'amour à la campagne"],"answer":"D'une famille qui s'installe en ville","explain":"主线是 qui quitte son village pour s'installer en ville，以及遇到的困难；其他概括都偏离原文。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0011","level":"B1","skill":"reading","prompt":"[阅读] Réduction accordée sous condition que l'achat soit effectué avant le 31 décembre. 问题：À quelle condition la réduction est-elle accordée ?","options":["Si l'achat est fait avant le 31 décembre","Si l'achat dépasse 100 €","Si le client a une carte de fidélité","Si le produit est défectueux"],"answer":"Si l'achat est fait avant le 31 décembre","explain":"sous condition que + 虚拟式（soit effectué）给出条件与期限；其他条件都没有出现。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0012","level":"B1","skill":"reading","prompt":"[阅读] Beaucoup de jeunes diplômés acceptent un emploi qui ne correspond pas à leur formation, faute de mieux. 问题：Pourquoi acceptent-ils ce type d'emploi ?","options":["Faute de mieux","Par choix de carrière","Pour le salaire élevé","Pour rester près de leur famille"],"answer":"Faute de mieux","explain":"faute de mieux ＝「没有更好的选择」；职业规划、高薪、离家近都不是文中原因。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0013","level":"B1","skill":"reading","prompt":"[阅读] Le gouvernement a annoncé un plan de soutien aux petites entreprises, qui prévoit des aides à la trésorerie et un report des charges. 问题：Que prévoit ce plan ?","options":["Des aides à la trésorerie et un report des charges","Une baisse de l'impôt sur le revenu","La création d'une nouvelle banque","La suppression des charges sociales"],"answer":"Des aides à la trésorerie et un report des charges","explain":"关系从句 qui prévoit… 列出两项措施；所得税、新银行、取消社保费用都不是原文内容。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0014","level":"B1","skill":"reading","prompt":"[阅读] Il est rare que les habitants participent aux réunions de quartier ; pourtant, les décisions les concernent directement. 问题：Que constate l'auteur ?","options":["Les habitants participent peu, alors que les décisions les concernent","Les habitants participent beaucoup","Les réunions sont inutiles","Les décisions ne concernent personne"],"answer":"Les habitants participent peu, alors que les décisions les concernent","explain":"il est rare que + 虚拟式表「很少发生」，pourtant 表转折：居民很少参与，但决定与他们直接相关。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0015","level":"B1","skill":"reading","prompt":"[阅读] La formation est ouverte à tous, à condition d'avoir un niveau B1 en français. 问题：Quelle est la condition d'inscription ?","options":["Avoir un niveau B1","Avoir plus de 25 ans","Travailler dans une entreprise","Habiter en France"],"answer":"Avoir un niveau B1","explain":"à condition de + 不定式给出唯一条件：法语 B1 水平；年龄、企业、居住地都没有被要求。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0016","level":"B1","skill":"reading","prompt":"[阅读] Ce film, qui a reçu trois prix internationaux, sera projeté gratuitement samedi à 20 h dans la salle municipale. 问题：Quelle information principale donne cette affiche ?","options":["Une projection gratuite samedi soir","Une projection payante","Une conférence","Un concert"],"answer":"Une projection gratuite samedi soir","explain":"sera projeté gratuitement samedi à 20 h 是核心信息；关系从句补充获奖情况，但不改变活动性质。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0017","level":"B1","skill":"reading","prompt":"[阅读] Nous regrettons de vous informer que votre demande n'a pas été retenue, en raison du nombre élevé de candidatures. 问题：Pourquoi la demande a-t-elle été refusée ?","options":["À cause du grand nombre de candidatures","Parce que le dossier était incomplet","Parce que la personne habite trop loin","Parce que la date limite était dépassée"],"answer":"À cause du grand nombre de candidatures","explain":"en raison du nombre élevé de candidatures 是明确理由；材料不全、距离、超期都没有出现。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"},{"id":"q-read-b1-0018","level":"B1","skill":"reading","prompt":"[阅读] Le musée propose des visites guidées pour les scolaires le matin, et des ateliers pour les familles le week-end. 问题：Qu'est-ce qui est proposé le week-end ?","options":["Des ateliers pour les familles","Des visites guidées pour les scolaires","Des concerts","Des conférences scientifiques"],"answer":"Des ateliers pour les familles","explain":"le week-end 与 ateliers pour les familles 对应；学生导览在工作日上午，音乐会和科学讲座都没有出现。","source":"阅读 · B1 短文与告示（compréhension écrite B1 · DELF）"}],"writing":[{"id":"q-writ-b1-0001","level":"B1","skill":"writing","prompt":"写作自评（让步从句），选出正确的一句：","options":["Bien que le sujet soit complexe, l'auteur l'explique clairement.","Bien que le sujet est complexe, l'auteur l'explique clairement.","Malgré le sujet est complexe, l'auteur l'explique clairement.","Bien que le sujet étant complexe, l'auteur l'explique clairement."],"answer":"Bien que le sujet soit complexe, l'auteur l'explique clairement.","explain":"bien que 后接虚拟式（soit）；est 是直陈式，malgré 只能接名词，étant 不能直接跟在 bien que 后面。自评标准：让步连词与语式一一对应。","source":"写作自评 · B1 让步（production écrite B1）"},{"id":"q-writ-b1-0002","level":"B1","skill":"writing","prompt":"写作自评（间接引语），选出时态推移正确的一句：","options":["Il m'a expliqué qu'il n'avait pas eu le temps de me répondre.","Il m'a expliqué qu'il n'a pas eu le temps de me répondre.","Il m'a expliqué qu'il n'aurait pas le temps de me répondre.","Il m'a expliqué de ne pas avoir eu le temps de me répondre."],"answer":"Il m'a expliqué qu'il n'avait pas eu le temps de me répondre.","explain":"主句过去时 + 从句动作更早，用愈过去时 avait eu；a eu 未推移，aurait 表后时，expliquer de + 不定式不是「解释」的搭配。","source":"写作自评 · B1 转述（production écrite B1）"},{"id":"q-writ-b1-0003","level":"B1","skill":"writing","prompt":"写作自评（间接强调结构），选出正确的一句：","options":["Ce qui me plaît dans ce livre, c'est la franchise de l'auteur.","Ce que me plaît dans ce livre, c'est la franchise de l'auteur.","Ce dont me plaît dans ce livre, c'est la franchise de l'auteur.","Ce qui me plaît dans ce livre, ce sont la franchise de l'auteur."],"answer":"Ce qui me plaît dans ce livre, c'est la franchise de l'auteur.","explain":"从句缺主语用 ce qui（plaire 的主语）；ce que 作宾语，ce dont 替代 de + 事物，表语是单数名词所以用 c'est 而不是 ce sont。","source":"写作自评 · B1 强调结构（production écrite B1）"},{"id":"q-writ-b1-0004","level":"B1","skill":"writing","prompt":"写作自评（提出对策），选出正确的一句：","options":["Si l'on veut réduire la pollution, il faut investir dans les transports publics.","Si l'on veut réduire la pollution, il faut que nous investissons dans les transports publics.","Si l'on veut réduire la pollution, il faut d'investir dans les transports publics.","Si l'on veut réduire la pollution, il faut investir dans transports publics."],"answer":"Si l'on veut réduire la pollution, il faut investir dans les transports publics.","explain":"泛指建议用 il faut + 不定式；il faut que 后必须虚拟式（investissions），falloir de 不成立，定冠词 les 不能省。","source":"写作自评 · B1 建议（production écrite B1）"},{"id":"q-writ-b1-0005","level":"B1","skill":"writing","prompt":"写作自评（礼貌正式请求），选出最规范的一句：","options":["Je vous serais reconnaissant de bien vouloir me communiquer votre réponse avant le 30 juin.","Je vous serai reconnaissant de bien vouloir me communiquer votre réponse avant le 30 juin.","Je vous serais reconnaissant de bien vouloir me communiquer votre réponse depuis le 30 juin.","Je vous serais reconnaissant que vous me communiquez votre réponse avant le 30 juin."],"answer":"Je vous serais reconnaissant de bien vouloir me communiquer votre réponse avant le 30 juin.","explain":"条件式 serais 表礼貌距离；serai 是将来时缺少委婉，depuis 表「从……起」与截止期矛盾，que 从句里用直陈式 communiquez 也不合规范（应 communiquiez）。","source":"写作自评 · B1 正式信函（production écrite B1）"},{"id":"q-writ-b1-0006","level":"B1","skill":"writing","prompt":"写作自评（并列连接），选出最恰当的一句：","options":["D'une part, le télétravail réduit les déplacements ; d'autre part, il isole les salariés.","D'une part, le télétravail réduit les déplacements ; d'autre part, il isole des salariés.","D'un part, le télétravail réduit les déplacements ; d'autre part, il isole les salariés.","D'une part, le télétravail réduit les déplacements ; de l'autre part, il isole les salariés."],"answer":"D'une part, le télétravail réduit les déplacements ; d'autre part, il isole les salariés.","explain":"固定搭配 d'une part… d'autre part 要对称；用 des salariés 破坏泛指，d'un part 是冠词误用，de l'autre part 是生造形式。","source":"写作自评 · B1 论述（production écrite B1）"},{"id":"q-writ-b1-0007","level":"B1","skill":"writing","prompt":"写作自评（无人称表达），选出正确的一句：","options":["Il est possible que le projet soit reporté à l'année prochaine.","Il est possible que le projet sera reporté à l'année prochaine.","Il est possible que le projet est reporté à l'année prochaine.","Il est possible le projet soit reporté à l'année prochaine."],"answer":"Il est possible que le projet soit reporté à l'année prochaine.","explain":"il est possible que + 虚拟式（soit reporté）；sera 和 est 是直陈式，漏掉 que 结构不成立。","source":"写作自评 · B1 推测（production écrite B1）"},{"id":"q-writ-b1-0008","level":"B1","skill":"writing","prompt":"写作自评（间接疑问），选出正确的一句：","options":["Je me demande si cette solution est vraiment efficace.","Je me demande est-ce que cette solution est vraiment efficace.","Je me demande que cette solution est vraiment efficace.","Je me demande si cette solution soit vraiment efficace."],"answer":"Je me demande si cette solution est vraiment efficace.","explain":"间接一般疑问用 si + 直陈式陈述语序；est-ce que 不能进入间接引语，que 不能引导一般疑问，si 从句不用虚拟式。","source":"写作自评 · B1 提问（production écrite B1）"},{"id":"q-writ-b1-0009","level":"B1","skill":"writing","prompt":"写作自评（时间从句的语式），选出正确的一句：","options":["Après qu'il a terminé son rapport, il a envoyé le dossier.","Après qu'il ait terminé son rapport, il a envoyé le dossier.","Après que d'avoir terminé son rapport, il a envoyé le dossier."],"answer":"Après qu'il a terminé son rapport, il a envoyé le dossier.","explain":"après que 按规范接直陈式（a terminé），先时关系由时态体现；把虚拟式（ait）加在 après que 后是常见但受争议的用法，que 与不定式叠用（après que d'avoir）则完全错误。","source":"写作自评 · B1 时间从句（production écrite B1）"},{"id":"q-writ-b1-0010","level":"B1","skill":"writing","prompt":"写作自评（让步），选出正确的一句：","options":["Bien qu'il soit jeune, il a déjà une grande expérience.","Bien qu'il est jeune, il a déjà une grande expérience.","Malgré qu'il soit jeune, il a déjà une grande expérience.","Malgré qu'il est jeune, il a déjà une grande expérience."],"answer":"Bien qu'il soit jeune, il a déjà une grande expérience.","explain":"bien que + 虚拟式（soit）；est 是直陈式，malgré que 被规范语法视为错误（应说 bien que + 虚拟式或 malgré + 名词）。","source":"写作自评 · B1 让步（production écrite B1）"},{"id":"q-writ-b1-0011","level":"B1","skill":"writing","prompt":"写作自评（主谓与性数配合），选出正确的一句：","options":["Plusieurs études montrent que le sommeil joue un rôle essentiel dans la mémoire.","Plusieurs études montrent que le sommeil joue un rôle essentielle dans la mémoire.","Plusieurs études montre que le sommeil joue un rôle essentiel dans la mémoire.","Plusieurs études montrent que le sommeil joue un rôle essentiels dans la mémoire."],"answer":"Plusieurs études montrent que le sommeil joue un rôle essentiel dans la mémoire.","explain":"主语 plusieurs études 是复数→montrent；rôle 是阳性单数→essentiel（essentielle 阴性、essentiels 复数都错）。","source":"写作自评 · B1 说明文（production écrite B1）"},{"id":"q-writ-b1-0012","level":"B1","skill":"writing","prompt":"写作自评（被动语态），选出正确的一句：","options":["Ce rapport a été rédigé par une équipe de chercheurs.","Ce rapport a été rédigé d'une équipe de chercheurs.","Ce rapport a rédigé par une équipe de chercheurs.","Ce rapport été rédigé par une équipe de chercheurs."],"answer":"Ce rapport a été rédigé par une équipe de chercheurs.","explain":"被动态是 être + 过去分词 + par 施动者；de 用于情感与状态类动词，缺助动词 être（c 与 d）都不成立。","source":"写作自评 · B1 被动（production écrite B1）"},{"id":"q-writ-b1-0013","level":"B1","skill":"writing","prompt":"写作自评（介词搭配），选出正确的一句：","options":["Il faudrait sensibiliser le public aux enjeux climatiques.","Il faudrait sensibiliser le public sur les enjeux climatiques.","Il faudrait sensibiliser le public des enjeux climatiques.","Il faudrait sensibiliser le public à les enjeux climatiques."],"answer":"Il faudrait sensibiliser le public aux enjeux climatiques.","explain":"sensibiliser qqn à qch，à + les 缩合为 aux；sur 和 de 都是误搭，à les 没有缩合。","source":"写作自评 · B1 搭配（production écrite B1）"},{"id":"q-writ-b1-0014","level":"B1","skill":"writing","prompt":"写作自评（原因表达），选出正确的一句：","options":["Grâce aux nouvelles technologies, le télétravail s'est largement développé.","À cause des nouvelles technologies, le télétravail s'est largement développé.","Grâce à les nouvelles technologies, le télétravail s'est largement développé.","Grâce des nouvelles technologies, le télétravail s'est largement développé."],"answer":"Grâce aux nouvelles technologies, le télétravail s'est largement développé.","explain":"积极原因用 grâce à（à + les → aux）；à cause de 用于消极原因，à les 未缩合，漏 à 结构不成立。","source":"写作自评 · B1 原因（production écrite B1）"},{"id":"q-writ-b1-0015","level":"B1","skill":"writing","prompt":"写作自评（无人称的必要性），选出正确的一句：","options":["Il est nécessaire de prendre des mesures immédiates.","Il est nécessaire que prendre des mesures immédiates.","Il est nécessaire prendre des mesures immédiates.","Il est nécessaire de prendre de mesures immédiates."],"answer":"Il est nécessaire de prendre des mesures immédiates.","explain":"无人称表达用 il est nécessaire de + 不定式；que 后面要接完整从句，漏 de 不成立，de mesures 是冠词误用（应为 des mesures）。","source":"写作自评 · B1 倡议（production écrite B1）"},{"id":"q-writ-b1-0016","level":"B1","skill":"writing","prompt":"写作自评（结论段），选出最连贯的一句：","options":["En conclusion, la réforme semble nécessaire, même si son application reste délicate.","En conclusion, la réforme semble nécessaire, malgré que son application reste délicate.","En conclusion, la réforme se semble nécessaire, même si son application reste délicate.","En conclusion, la réforme semble nécessaire, alors que son application reste délicate."],"answer":"En conclusion, la réforme semble nécessaire, même si son application reste délicate.","explain":"malgré que 不合规范，se sembler 结构错误（sembler 不用代词式），alors que 表对立而非让步，会改变句子的逻辑关系。","source":"写作自评 · B1 结论（production écrite B1）"}],"speaking":[{"id":"q-speak-b1-0001","level":"B1","skill":"speaking","prompt":"口语自评（表达立场），选出正确的一句：","options":["À mon avis, cette mesure est nécessaire, même si elle est impopulaire.","À mon avis, cette mesure est nécessaire, même si elle soit impopulaire.","À mon avis, cette mesure est nécessaire, bien qu'elle est impopulaire.","À mon avis, cette mesure est nécessaire, malgré elle est impopulaire."],"answer":"À mon avis, cette mesure est nécessaire, même si elle est impopulaire.","explain":"même si 接直陈式（est）；bien que 才要求虚拟式（soit），malgré 只能接名词。自评标准：每个连接词对应的语式是否正确。","source":"口语自评 · B1 表达观点（production orale B1）"},{"id":"q-speak-b1-0002","level":"B1","skill":"speaking","prompt":"口语自评（委婉表达不同意），选出最得体的一句：","options":["Je comprends votre point de vue, mais je ne partage pas entièrement votre analyse.","Vous avez tort.","Je ne suis pas d'accord, point.","Je comprends votre point de vue, mais je ne partage pas à votre analyse."],"answer":"Je comprends votre point de vue, mais je ne partage pas entièrement votre analyse.","explain":"先承认再保留是专业的表达方式；Vous avez tort 过于直接，Je ne suis pas d'accord, point 缺少论证，partager 是直接及物动词（不用 à）。","source":"口语自评 · B1 讨论（production orale B1）"},{"id":"q-speak-b1-0003","level":"B1","skill":"speaking","prompt":"口语自评（请对方澄清用词），选出正确的一句：","options":["Pourriez-vous préciser ce que vous entendez par « efficacité » ?","Pourriez-vous préciser ce que vous entendez d'« efficacité » ?","Pourriez-vous préciser que vous entendez par « efficacité » ?","Pourriez-vous préciser ce que vous entendez « efficacité » ?"],"answer":"Pourriez-vous préciser ce que vous entendez par « efficacité » ?","explain":"entendre par qch（把……理解为）是固定搭配；de 是误搭，漏 ce que 缺间接宾语，漏 par 结构不完整。","source":"口语自评 · B1 澄清（production orale B1）"},{"id":"q-speak-b1-0004","level":"B1","skill":"speaking","prompt":"口语自评（有保留的同意），选出正确的一句：","options":["Je suis globalement d'accord, sous réserve que des garanties soient apportées.","Je suis globalement d'accord, sous réserve que des garanties sont apportées.","Je suis globalement d'accord, sous réserve de que des garanties soient apportées.","Je suis globalement d'accord, sous réserve des garanties soient apportées."],"answer":"Je suis globalement d'accord, sous réserve que des garanties soient apportées.","explain":"sous réserve que + 虚拟式（soient apportées）；直陈式 sont 错，de que 叠用错，漏 que 结构不成立。","source":"口语自评 · B1 谈判（production orale B1）"},{"id":"q-speak-b1-0005","level":"B1","skill":"speaking","prompt":"口语自评（礼貌地打断补充），选出正确的一句：","options":["Excusez-moi de vous interrompre, je voudrais ajouter un point.","Excusez-moi de vous interrompez, je voudrais ajouter un point.","Excusez-moi vous interrompre, je voudrais ajouter un point.","Excusez-moi de vous interrompre, je voudrais ajouter à un point."],"answer":"Excusez-moi de vous interrompre, je voudrais ajouter un point.","explain":"excuser de + 不定式；interrompez 是变位形式，漏 de 不成立，ajouter 直接接宾语（不加 à）。","source":"口语自评 · B1 讨论（production orale B1）"},{"id":"q-speak-b1-0006","level":"B1","skill":"speaking","prompt":"口语自评（转述他人发言），选出正确的一句：","options":["Le ministre a déclaré que la réforme entrerait en vigueur en 2027.","Le ministre a déclaré que la réforme entrera en vigueur en 2027.","Le ministre a déclaré la réforme entrerait en vigueur en 2027.","Le ministre a déclaré que la réforme entrerait en vigueur dans 2027."],"answer":"Le ministre a déclaré que la réforme entrerait en vigueur en 2027.","explain":"主句过去时，从句表将来要用条件式（entrerait）；entrera 未推移，漏 que 不成立，年份前用 en 而不是 dans。","source":"口语自评 · B1 转述（production orale B1）"},{"id":"q-speak-b1-0007","level":"B1","skill":"speaking","prompt":"口语自评（谨慎表态），选出正确的一句：","options":["Il me semble que cette solution présente des risques.","Il me semble que cette solution présent des risques.","Il me semble que cette solution soit présente des risques.","Il me semble que cette solution présente de risques."],"answer":"Il me semble que cette solution présente des risques.","explain":"il me semble que 接直陈式（présente）；présent 缺变位，soit présente 语式与结构都错，des risques 是不定复数冠词（不能用 de）。","source":"口语自评 · B1 表达态度（production orale B1）"},{"id":"q-speak-b1-0008","level":"B1","skill":"speaking","prompt":"口语自评（提出建议），选出正确的一句：","options":["Je vous suggère de relire le rapport avant la réunion.","Je vous suggère relire le rapport avant la réunion.","Je vous suggère que vous relirez le rapport avant la réunion.","Je vous suggère à relire le rapport avant la réunion."],"answer":"Je vous suggère de relire le rapport avant la réunion.","explain":"suggérer à qqn de faire qch；漏 de 不成立，que 从句该用虚拟式（relisiez）而不是将来时，à 是误搭。","source":"口语自评 · B1 建议（production orale B1）"},{"id":"q-speak-b1-0009","level":"B1","skill":"speaking","prompt":"口语自评（澄清误解），选出正确的一句：","options":["Je crains que vous ne m'ayez mal compris.","Je crains que vous ne m'avez mal compris.","Je crains que vous ne m'ayez mal comprit.","Je crains que vous ne m'ayez mal comprendre."],"answer":"Je crains que vous ne m'ayez mal compris.","explain":"craindre que + 虚拟式（ayez compris，ne 为赘词）；avez 是直陈式，comprit 和 comprendre 都不是正确的过去分词形式。","source":"口语自评 · B1 澄清（production orale B1）"},{"id":"q-speak-b1-0010","level":"B1","skill":"speaking","prompt":"口语自评（请求延期），选出正确的一句：","options":["Serait-il possible d'obtenir un délai supplémentaire de deux semaines ?","Serait-il possible obtenir un délai supplémentaire de deux semaines ?","Est-il possible que d'obtenir un délai supplémentaire de deux semaines ?","Serait-il possible d'obtenir un délai supplémentaire pendant deux semaines ?"],"answer":"Serait-il possible d'obtenir un délai supplémentaire de deux semaines ?","explain":"possible 后要 de + 不定式（漏 de 不成立）；que 与不定式叠用错误；pendant deux semaines 表持续时长，与「延长两周」的语义不符。","source":"口语自评 · B1 请求（production orale B1）"},{"id":"q-speak-b1-0011","level":"B1","skill":"speaking","prompt":"口语自评（正式道歉），选出正确的一句：","options":["Je tenais à vous présenter mes excuses pour ce retard.","Je tenais vous présenter mes excuses pour ce retard.","Je tenais à vous présenter mes excuses de ce retard.","Je tenais à vous présenter mes excuses à ce retard."],"answer":"Je tenais à vous présenter mes excuses pour ce retard.","explain":"tenir à + 不定式（漏 à 不成立）；道歉原因用 pour（pour ce retard），de 和 à 都是误搭。","source":"口语自评 · B1 道歉（production orale B1）"},{"id":"q-speak-b1-0012","level":"B1","skill":"speaking","prompt":"口语自评（委婉拒绝提议），选出正确的一句：","options":["Votre proposition est intéressante, mais elle me semble difficile à mettre en œuvre dans les délais.","Votre proposition est intéressante, mais elle me semble difficile mettre en œuvre dans les délais.","Votre proposition est intéressante, mais elle me semble difficile de mettre en œuvre dans les délais.","Votre proposition est intéressante, mais elle me semble difficile à se mettre en œuvre dans les délais."],"answer":"Votre proposition est intéressante, mais elle me semble difficile à mettre en œuvre dans les délais.","explain":"difficile 后接 à + 不定式（difficile à mettre en œuvre）；漏 à 与用 de 都不合规范，se mettre 会改变主语关系。","source":"口语自评 · B1 谈判（production orale B1）"},{"id":"q-speak-b1-0013","level":"B1","skill":"speaking","prompt":"口语自评（询问负责人），选出正确的一句：","options":["Pourriez-vous m'indiquer qui sera responsable du suivi du dossier ?","Pourriez-vous m'indiquer qui serai responsable du suivi du dossier ?","Pourriez-vous m'indiquer que sera responsable du suivi du dossier ?","Pourriez-vous m'indiquer qui sera responsable le suivi du dossier ?"],"answer":"Pourriez-vous m'indiquer qui sera responsable du suivi du dossier ?","explain":"疑问词 qui 作从句主语，动词第三人称单数 sera；serai 是 je 的形式，que 不能替代主语 qui，responsable 后要有介词 de（responsable du suivi）。","source":"口语自评 · B1 询问（production orale B1）"},{"id":"q-speak-b1-0014","level":"B1","skill":"speaking","prompt":"口语自评（表达不确定），选出正确的一句：","options":["Je n'en suis pas certain, mais il me semble que c'est la meilleure option.","Je ne suis pas en certain, mais il me semble que c'est la meilleure option.","Je n'en suis pas certain, mais il me semble que c'est la meilleur option.","Je n'en suis certain pas, mais il me semble que c'est la meilleure option."],"answer":"Je n'en suis pas certain, mais il me semble que c'est la meilleure option.","explain":"代词 en 要放在助动词/系动词前（n'en suis pas）；en 位置错、meilleur 缺阴性配合（option 阴性→meilleure）、pas 位置错都是常见错误。","source":"口语自评 · B1 表达态度（production orale B1）"},{"id":"q-speak-b1-0015","level":"B1","skill":"speaking","prompt":"口语自评（确认对方观点），选出正确的一句：","options":["Vous disiez donc que le problème vient d'un manque de coordination ?","Vous disiez donc le problème vient d'un manque de coordination ?","Vous disiez donc que le problème vient d'un manque à coordination ?","Vous disiez donc que le problème vient d'un manque de coordonner ?"],"answer":"Vous disiez donc que le problème vient d'un manque de coordination ?","explain":"转述从句必须有 que；manquer 的名词化是 la coordination（不能用动词原形 coordonner），介词用 de。","source":"口语自评 · B1 讨论（production orale B1）"},{"id":"q-speak-b1-0016","level":"B1","skill":"speaking","prompt":"口语自评（结束讨论），选出最得体的一句：","options":["Nous pourrions peut-être conclure sur ce point et fixer une prochaine réunion.","Nous pourrons peut-être conclure sur ce point et fixer une prochaine réunion.","Nous pourrions peut-être conclure sur ce point et fixer à une prochaine réunion.","Nous pourrions peut-être conclure sur ce point et fixer une prochain réunion."],"answer":"Nous pourrions peut-être conclure sur ce point et fixer une prochaine réunion.","explain":"条件式 pourrions 表委婉建议；pourrons 是将来时缺少商量语气，fixer 直接接宾语（不用 à），réunion 是阴性所以用 prochaine。","source":"口语自评 · B1 会议（production orale B1）"}]}}.B1;
